local trailBattleMgr

------------ define ------------


---@class TrailStageChallengeTeamLayout
---@field HeadNode                      	UnityEngine.RectTransform
local TrailStageChallengeTeamLayout = Class("TrailStageChallengeTeamLayout")
function TrailStageChallengeTeamLayout:__init()
    self.btnAction = nil
    self.enemyGoList = {}
    self.myTeamGoList = {}

end

function TrailStageChallengeTeamLayout:__delete()
    self.btnAction = nil
    self.enemyGoList = nil
    self.myTeamGoList = nil
    self.controller = nil
end

---SetCallBack
---设置单击回调函数
function TrailStageChallengeTeamLayout:SetBtnCallBack(cb)
    self.btnAction = cb
end

function TrailStageChallengeTeamLayout:Awake()
    trailBattleMgr = TrailBattleMgr:GetInstance()
    UIEventProxy.Create(self.controller.gameObject).onPointerClick = function()
        if type(self.btnAction) == 'function' then
            self.btnAction()
        end
    end
end

function TrailStageChallengeTeamLayout:FreshEnemyTeam(teamMemberData)
    for i = 1, #teamMemberData do
        local go
        go = self.enemyGoList[i]
        if not go then
            go = CfUtils.InstantiateGo(self.HeadNode, self.controller.gameObject)
            go.name = "Node"..i
            self.enemyGoList[i] = go.gameObject
        end
        local goEnv = CfUtils.GetLuaScr(go.transform:Find("CommonSmallHeadNode"), "Game.Behaviours.CardHeadNode")
        --goEnv:FreshMonsterUI(teamMemberData[i])
        local monsterTypeData = CfUtils.GetCfVo(AutoIds.IdSetting39, "MonsterTypeVo", teamMemberData[i].id)
        if isNull(monsterTypeData) then--助战
            goEnv:FreshNode(teamMemberData[i])
            goEnv:SetLvStatus(true)
        else
            goEnv:FreshMonsterUI(monsterTypeData, teamMemberData[i].rare)
            goEnv:SetStarStatus(false)
            goEnv:SetBottomImageStatus(false)
        end
        KTool.SetActive(go, true)
    end

end

function TrailStageChallengeTeamLayout:FreshMyTeam(teamMemberData, cb)
    for i = 1, #teamMemberData do
        local go
        go = self.myTeamGoList[i]
        if not go then
            go = CfUtils.InstantiateGo(self.HeadNode, self.controller.gameObject)
            go.name = "Node"..i
            self.myTeamGoList[i] = go.gameObject
        end
        local hasMember = table.count(teamMemberData[i]) > 0
        local headNode = go.transform:Find("CommonSmallHeadNode")
        KTool.SetActive(headNode, hasMember)
        if hasMember then
            local goEnv = CfUtils.GetLuaScr(headNode, "Game.Behaviours.CardHeadNode")
            local cardDojo = cardComponent:GetCardById(teamMemberData[i].refId)
            if cardDojo then
                goEnv:FreshNode(cardDojo, true)
                goEnv:SetCallBack(function()
                    cb()
                end)
            end
        else
            SetButtonAction(go.transform:Find("BtnAdd"), function()
                cb()
            end)
        end
        KTool.SetActive(go, true)
    end
end

function TrailStageChallengeTeamLayout:OnDestroy()
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
    self = nil --lua层的gc需要
end

return TrailStageChallengeTeamLayout